CREATE VIEW dbo.IV_Q$PESQ_SATISFACAO_PECA ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , CORTESIA_DO_VENDEDOR, Q002_INSATISFEITO, Q002_INDIFERENTE, Q002_SATISFEITO, Q003_INSATISFEITO, Q003_INDIFERENTE, Q003_SATISFEITO, Q004_INSATISFEITO, Q004_INDIFERENTE, Q004_SATISFEITO, RECOMENDAR_PECAS_JD, Q006_INSATISFEITO, Q006_INDIFERENTE, Q006_SATISFEITO, Q007_ESTRUTURA, Q007_AREA_DE_VENDAS, Q007_AREA_DE_PECAS, Q007_AREA_DE_SERVICO, Q007_ORGANIZACAO, Q007_ESPACO_FISICO, Q007_OUTROS, Q008_ZERO, Q008_UM, Q008_DOIS, Q008_TRES, Q008_QUATRO, Q008_CINCO, Q008_SEIS, Q008_SETE, Q008_OITO, Q008_NOVE, Q008_DEZ)     AS SELECT PES.SEQPESSOA, PES.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.CORTESIA_DO_VENDEDOR, TABF.Q002_INSATISFEITO, TABF.Q002_INDIFERENTE, TABF.Q002_SATISFEITO, TABF.Q003_INSATISFEITO, TABF.Q003_INDIFERENTE, TABF.Q003_SATISFEITO, TABF.Q004_INSATISFEITO, TABF.Q004_INDIFERENTE, TABF.Q004_SATISFEITO, TABF.RECOMENDAR_PECAS_JD, TABF.Q006_INSATISFEITO, TABF.Q006_INDIFERENTE, TABF.Q006_SATISFEITO, TABF.Q007_ESTRUTURA, TABF.Q007_AREA_DE_VENDAS, TABF.Q007_AREA_DE_PECAS, TABF.Q007_AREA_DE_SERVICO, TABF.Q007_ORGANIZACAO, TABF.Q007_ESPACO_FISICO, TABF.Q007_OUTROS, TABF.Q008_ZERO, TABF.Q008_UM, TABF.Q008_DOIS, TABF.Q008_TRES, TABF.Q008_QUATRO, TABF.Q008_CINCO, TABF.Q008_SEIS, TABF.Q008_SETE, TABF.Q008_OITO, TABF.Q008_NOVE, TABF.Q008_DEZ    FROM  IV_Q_PESQ_SATISFACAO_PECA TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA PES ON PES.SEQPESSOA = QST.SEQPESSOA 